<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\TruckService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('TRUCK_REVIEW_QUEUE_VIEW');$id=(int)($_GET['id']??0);$errors=[];$t=TruckService::review($id);if(!$t){http_response_code(404);exit('Truck verification not found.');}if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{TruckService::decide($id,(int)Auth::user()['id'],(string)($_POST['decision']??''),(string)($_POST['reason']??''));header('Location: '.Url::to('operations/trucks.php?saved=1'));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}}$pageTitle='Truck Verification';require BASE_PATH.'/app/Views/layout/header.php';$today=gmdate('Y-m-d');$compliant=$t['result_code']==='PASS'&&$t['roadworthiness_status']==='ROADWORTHY'&&$t['inspection_expires_on']>=$today&&$t['insurance_valid_to']>=$today;?><div class="page-head"><div><h1><?=h($t['registration_number'])?></h1><p><?=h(($t['owner_company_name']?:$t['owner_user_name']).' · '.$t['make_name'].' '.$t['model_name'])?></p></div><span class="badge"><?=h($t['case_status'])?></span></div><?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?><div class="<?=h($compliant?'success':'error')?>"><strong>Compliance precheck: <?=h($compliant?'PASS':'FAIL')?></strong><br>Approval requires PASS, ROADWORTHY, and unexpired insurance and inspection references.</div><div class="grid"><div class="card"><h3>Truck</h3><p><?=h(str_replace('_',' ',$t['body_type_code']))?> · <?=h($t['capacity_value'].' '.$t['capacity_unit'])?></p><p>Chassis: <?=h($t['chassis_number'])?></p></div><div class="card"><h3>Insurance</h3><p><?=h($t['provider_name'].' · '.$t['policy_number'])?></p><p><?=h($t['coverage_type'])?></p><p><?=h($t['insurance_valid_from'].' – '.$t['insurance_valid_to'])?></p></div><div class="card"><h3>Inspection</h3><p><?=h($t['inspection_number'])?></p><p><?=h($t['result_code'].' · '.$t['roadworthiness_status'])?></p><p><?=h($t['inspected_on'].' – '.$t['inspection_expires_on'])?></p></div></div><?php if($t['case_status']==='pending'):?><div class="decision-grid" style="margin-top:18px"><?php if(Auth::can('TRUCK_REVIEW_APPROVE')):?><form method="post" class="card"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="decision" value="approved"><div class="field"><label>Approval note <span class="muted">(optional)</span></label><textarea name="reason" maxlength="2000" rows="4"></textarea></div><button class="button" style="margin-top:12px" <?=$compliant?'':'disabled'?>>Approve truck</button></form><?php endif;?><?php if(Auth::can('TRUCK_REVIEW_REJECT')):?><form method="post" class="card"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="decision" value="rejected"><div class="field"><label>Rejection reason</label><textarea name="reason" minlength="10" maxlength="4000" rows="4" required></textarea></div><button class="button danger" style="margin-top:12px">Reject truck</button></form><?php endif;?></div><?php endif;?><?php require BASE_PATH.'/app/Views/layout/footer.php';
